import itertools

def find_partitions():
    results = []
    for S in range(95, 115):
        values = list(range(S, S+14))
        D = 14*S - 1241

        # Check if D is achievable as sum of 2 distinct values from the set
        diag_pairs = []
        for pair in itertools.combinations(values, 2):
            if sum(pair) == D:
                diag_pairs.append(pair)

        if not diag_pairs:
            continue

        for diag_pair in diag_pairs:
            remaining = [v for v in values if v not in diag_pair]
            # Need to split remaining 12 into two groups of 6, each summing to 666
            for rows_combo in itertools.combinations(remaining, 6):
                if sum(rows_combo) == 666:
                    cols_combo = tuple(v for v in remaining if v not in rows_combo)
                    if sum(cols_combo) == 666:
                        results.append((S, diag_pair, rows_combo, cols_combo))
                        break  # one is enough per diag_pair
    return results

results = find_partitions()
print(f"Found {len(results)} possible sum assignments")
for S, diag, rows, cols in results:
    print(f"S={S}: diag={diag}, rows={sorted(rows)}, cols={sorted(cols)}")
